    int index = i;
    while (index < bb.limit()) {
        int b = bb.get(index) & 0xFF;
        if ((b & 0x80) == 0) {
            sb.append((char) b);
            index++;
        } else if ((b & 0xE0) == 0xC0) {
            int b1 = bb.get(index + 1) & 0xFF;
            if ((b1 & 0xC0) != 0x80) {
