public void generateGraph(Graph<V,E> target, Map<String, V> resultMap) {
    // Check if the target graph is null
    if (target == null) {
        throw new IllegalArgumentException("Target graph cannot be null");
    }

    // Check if the result map is null
    if (resultMap == null) {
        throw new IllegalArgumentException("Result map cannot be null");
    }

    // Create a new graph with the same vertex and edge types as the target graph
    Graph<V, E> graph = new Graph<>(target.getVertexType(), target.getEdgeType());

    // Add vertices to the graph
    for (String vertex : resultMap.keySet()) {
        graph.addVertex(vertex);
    }

    // Add edges to the graph
    for (String vertex : resultMap.keySet()) {
        for (String neighbor : resultMap.get(vertex)) {
            graph.addEdge(vertex, neighbor);
        }
    }

    // Set the graph as the target graph
    target.setGraph(graph);
}

