public byte[] toByteArray() {
    // Initialize an empty byte array to store the contents of the buffer(s)
    byte[] result = new byte[0];

    // Iterate over each buffer in the list
    for (ByteBuffer buffer : buffers) {
      // Get the current position of the buffer
      int pos = buffer.position();

      // Get the limit of the buffer
      int limit = buffer.limit();

      // Check if the buffer has remaining bytes
      if (pos < limit) {
        // Get the remaining bytes in the buffer
        byte[] bytes = new byte[limit - pos];
        buffer.get(bytes);

        // Append the bytes to the result array
        result = Arrays.copyOf(result, result.length + bytes.length);
        System.arraycopy(bytes, 0, result, result.length - bytes.length, bytes.length);
      }
    }

    // Return the result array
    return result;
  }

