public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new IllegalArgumentException("Array cannot be null");
    }
    if (from < 0 || from >= arr.length) {
        throw new IndexOutOfBoundsException("From index is out of bounds");
    }
    if (to < 0 || to >= arr.length) {
        throw new IndexOutOfBoundsException("To index is out of bounds");
    }
    if (from > to) {
        throw new IllegalArgumentException("From index must be less than or equal to to index");
    }

    int i = from, j = to;
    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

